from taf.internal.bmc.interfaces.bmc import Bmc, BmcConfiguration


class RedfishConfiguration(BmcConfiguration):
    """
    Configuration for all Redfish interfaces
    """
    default_http_protocol = "https"


class Redfish(Bmc):
    """
    Base class for all Redfish interface versions.
    [FDEV] Shall contain auto discovery of interface version in the future.
    """

    def __del__(self):
        """
        It is mandatory to logout on redfish interfaces.
        """
        self.logout()

    def logout(self):
        """
        Logout from Redfish interface.
        If session authentication was used: also frees up sessions on server.
        """
        if self.protocol:
            self.protocol.logout()
